// Generated by wasm-pack before TypeScript is compiled.
import initializeWasm, {
  diagnose as rustDiagnose,
  diagnose_offline as rustDiagnoseOffline,
  examples as rustExamples,
  report_to_markdown as rustReportToMarkdown,
// @ts-expect-error See the generated-module note above.
} from "./browser/why712_wasm.js";

import type { DiagnoseRequest, DiagnosticReport, ExampleSummary } from "./types.js";

export type {
  ComputedValues,
  Confidence,
  DiagnoseRequest,
  DiagnosticContext,
  DiagnosticFinding,
  DiagnosticReport,
  ExampleSummary,
  Hex,
  Severity,
  Verdict,
} from "./types.js";

let initialization: Promise<unknown> | undefined;

/** Loads the embedded Rust/WebAssembly diagnosis engine. Safe to call more than once. */
export function initialize(): Promise<unknown> {
  if (initialization === undefined) {
    const pending = initializeWasm(
      new URL("./browser/why712_wasm_bg.wasm", import.meta.url),
    );
    initialization = pending;
    return pending;
  }
  return initialization;
}

/** Runs deterministic diagnosis without contacting an RPC endpoint. */
export async function diagnoseOffline(input: DiagnoseRequest): Promise<DiagnosticReport> {
  await initialize();
  return rustDiagnoseOffline(input) as DiagnosticReport;
}

/** Acquires optional RPC evidence and runs the Rust diagnosis engine. */
export async function diagnose(input: DiagnoseRequest): Promise<DiagnosticReport> {
  await initialize();
  return rustDiagnose(input) as Promise<DiagnosticReport>;
}

/** Renders a report as GitHub-flavored Markdown. */
export async function reportToMarkdown(report: DiagnosticReport): Promise<string> {
  await initialize();
  return rustReportToMarkdown(report) as string;
}

/** Returns the reproducible examples bundled into the Rust engine. */
export async function examples(): Promise<ExampleSummary[]> {
  await initialize();
  return rustExamples() as ExampleSummary[];
}
